        /// <summary>An integer/double pair from the glyph tables.</summary>
        public readonly struct IntDoublePair
        {
            /// <summary>Integer part.</summary>
            public int First { get; }

            /// <summary>Double part.</summary>
            public double Second { get; }

            /// <summary>Build a pair.</summary>
            public IntDoublePair(int first, double second)
            {
                First = first;
                Second = second;
            }
        }

        /// <summary>A named colour triple.</summary>
        public sealed class NamedColor
        {
            /// <summary>Colour name.</summary>
            public string Name { get; }

            /// <summary>RGB triple.</summary>
            public double[] Rgb { get; }

            /// <summary>Build a named colour.</summary>
            public NamedColor(string name, double[] rgb)
            {
                Name = name;
                Rgb = rgb;
            }
        }

